vec3 colorA = vec3(1.0, 0.098, 0.416);
vec3 colorB = vec3(0.039, 0.031, 0.722);
vec3 colorC = vec3(0.039, 0.498, 0.929);

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{

    vec2 uv = fragCoord / iResolution.xy;

    vec2 st = uv;

    vec3 color = vec3(0.0);


    for(float i = 1.0; i < 12.0; i++){
        st.y += .1 / i * sin(uv.x * i * i + iTime * i * .2) * sin(uv.y * i * i + iTime * i * .5);

    }

    vec3 waves = mix(colorB, colorC, smoothstep(.05, .1, uv.y * st.y) + abs(sin(iTime * .2)));
    vec3 sunset = mix(colorC, colorA, smoothstep(.2, .8, uv.y));


    color = mix(waves, sunset, uv.y);


    fragColor = vec4(color,1.0);
}
